arguments.command:
python3 -c "
import json,re,collections
for f in ['results/eval_before.json.items.jsonl','results/eval_after.json.items.jsonl']:
    items=[json.loads(l) for l in open(f)]
    print('===',f)
    pats={'hash':r'####','boxed':r'\\\\boxed','answer_is':r'(?i)the answer is','therefore':r'(?i)therefore','dollar':r'\\\$'}
    for k,p in pats.items():
        print(k, sum(1 for i in items if re.search(p,i['text'])))
    print('ends with period', sum(1 for i in items if i['text'].strip().endswith('.')))
"

